import { test, expect } from '@playwright/test';

test.describe('Modal Accessibility Tests', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('https://your-application-url.com');
  });

  test('should announce modal title when opened', async ({ page }) => {
    await page.getByRole('button', { name: /open modal/i }).click();
    const modalTitle = await page.getByRole('heading', { name: /modal title/i });
    await expect(modalTitle).toBeVisible();
    await expect(modalTitle).toHaveAttribute('aria-live', 'assertive');
  });

  test('should not announce modal title when closed', async ({ page }) => {
    await page.getByRole('button', { name: /open modal/i }).click();
    await page.getByRole('button', { name: /close modal/i }).click();
    const modalTitle = await page.getByRole('heading', { name: /modal title/i });
    await expect(modalTitle).not.toBeVisible();
  });
});
